INSERT INTO `reports` VALUES (1,10,'001/LAP-SIDEPSIL/VIII/2026','2026-08-04','Kepala Bidang',NULL,NULL,NULL,'draft','reports/report-1.pdf',NULL,NULL,NULL,'2026-08-04 05:56:09','2026-09-28 01:49:11','2026-09-28 01:49:11'),(2,11,'002/LAP-SIDEPSIL/VIII/2026','2026-08-04','Kepala Bidang','Pemindaian terhadap sitara.simpeda.id menemukan 2 temuan pada 1 kategori ancaman: foreign_file.','Website sitara.simpeda.id dinyatakan AMAN dengan skor risiko 30/100.','Periksa dan hapus file asing yang tidak dikenal pada direktori aset/upload. Lanjutkan pemantauan rutin sesuai jadwal.','draft','reports/report-2.pdf',NULL,NULL,NULL,'2026-08-04 06:05:33','2026-09-28 01:49:11','2026-09-28 01:49:11'),(3,12,'003/LAP-SIDEPSIL/VIII/2026','2026-08-04','Kepala Bidang','Pemindaian terhadap Website Dinas Kesehatan menemukan 15 temuan pada 2 kategori ancaman: iframe, external_link.','Website Website Dinas Kesehatan TERINDIKASI mengandung konten atau skrip berbahaya dengan skor risiko 100/100.','Hapus elemen iframe mencurigakan dan batasi sumber konten yang dapat disisipkan. Audit tautan eksternal yang tidak relevan dengan konten resmi OPD. Segera nonaktifkan sementara akses publik dan lakukan investigasi menyeluruh.','draft','reports/report-3.pdf',NULL,NULL,NULL,'2026-08-04 06:22:47','2026-08-14 01:17:11','2026-08-14 01:17:11'),(4,26,'004/LAP-SIDEPSIL/VIII/2026','2026-08-05','Kepala Bidang','Pemindaian terhadap sisper.web.id tidak menemukan indikasi ancaman pada seluruh halaman yang diperiksa.','Website sisper.web.id dinyatakan AMAN dengan skor risiko 0/100.','Lanjutkan pemantauan rutin sesuai jadwal.','final','reports/report-4.pdf',NULL,NULL,NULL,'2026-08-05 06:23:05','2026-09-28 01:49:11','2026-09-28 01:49:11'),(5,32,'005/LAP-SIDEPSIL/VIII/2026','2026-08-06','Kepala Bidang','Pemindaian terhadap Website PUPR menemukan 25 temuan pada 3 kategori ancaman: iframe, external_link, backdoor.','Website Website PUPR TERINDIKASI mengandung konten atau skrip berbahaya dengan skor risiko 100/100.','Hapus el